<?php
require_once dirname(__DIR__) . '/config/config.php'; require_once dirname(__DIR__) . '/config/database.php'; require_once dirname(__DIR__) . '/config/functions.php'; require_once dirname(__DIR__) . '/config/session.php';
Session::start(); if (!Session::isLoggedIn() || Session::getUserRole() !== 'nanny') { header('Location: ' . APP_URL . dashboard_for_role(Session::getUserRole())); exit(); }
$pageTitle=t('dashboard.nanny_title');$active='dashboard';$uid=Session::getUserId();
$me=dbFetchOne("SELECT u.*,r.name_ar role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$uid]);
$stats=dbFetchOne("SELECT COUNT(DISTINCT f.id) total_families,COUNT(DISTINCT fc.id) total_children,COALESCE(SUM(CASE WHEN sp.status='active' THEN sp.monthly_amount ELSE 0 END),0) total_monthly FROM families f LEFT JOIN family_children fc ON fc.family_id=f.id AND fc.is_active=1 LEFT JOIN sponsorships sp ON sp.child_id=fc.id AND sp.status='active' WHERE f.nanny_id=? AND f.status IN ('active','pending')",[$uid]);
$ver=dbFetchOne("SELECT COUNT(*) fully_verified FROM nanny_family_verifications WHERE nanny_id=? AND month=? AND is_orphan_verified=1 AND is_mother_contact_verified=1 AND is_bank_verified=1",[$uid,date('Y-m')]);
$ageOuts=dbFetchAll("SELECT fc.child_name,fc.birth_date,f.mother_name,f.id family_id FROM family_children fc JOIN families f ON f.id=fc.family_id WHERE f.nanny_id=? AND fc.is_active=1 AND fc.birth_date IS NOT NULL AND fc.birth_date BETWEEN DATE_SUB(CURDATE(),INTERVAL 18 YEAR) AND DATE_SUB(CURDATE(),INTERVAL 17 YEAR) ORDER BY fc.birth_date ASC",[$uid]);
$families=dbFetchAll("SELECT f.id,f.family_code,f.mother_name,f.status,f.children_count FROM families f WHERE f.nanny_id=? ORDER BY f.updated_at DESC LIMIT 10",[$uid]);
$pending_batches=dbFetchAll("SELECT d.id disbursement_id,d.month,d.total_amount,og.group_name,(SELECT COUNT(*) FROM disbursement_items WHERE disbursement_id=d.id) total_families,(SELECT COUNT(*) FROM disbursement_items WHERE disbursement_id=d.id AND status='paid') confirmed_families,(SELECT COUNT(*) FROM disbursement_items WHERE disbursement_id=d.id AND status='pending') pending_families FROM monthly_disbursements d LEFT JOIN orphan_groups og ON og.id=d.group_id WHERE d.nanny_id=? AND d.status='transferred' ORDER BY d.created_at DESC",[$uid]);
$total_families_transferred=array_sum(array_column($pending_batches,'total_families'));$total_confirmed_families=array_sum(array_column($pending_batches,'confirmed_families'));$overall_progress=$total_families_transferred>0?round(($total_confirmed_families/$total_families_transferred)*100):0;
include dirname(__DIR__).'/includes/header.php';
?>
<div class="welcome-section fade-in"><h2><?php echo e(t('dashboard.welcome_user',['name'=>$me['full_name']??''])); ?></h2><p><?php echo e(t('dashboard.nanny_intro')); ?></p><div class="quick-actions mt-3"><a href="<?php echo url('modules/accounting/group_verification.php'); ?>" class="btn btn-info btn-sm me-2"><i class="fas fa-clipboard-check me-1"></i><?php echo e(t('dashboard.verify_groups')); ?></a><a href="<?php echo url('modules/accounting/disbursements.php'); ?>" class="btn btn-primary btn-sm me-2"><i class="fas fa-money-check-dollar me-1"></i><?php echo e(t('navigation.monthly_transfers')); ?></a><a href="<?php echo url('modules/accounting/returned_funds_nanny.php'); ?>" class="btn btn-success btn-sm me-2"><i class="fas fa-hand-holding-dollar me-1"></i>إعادة صرف المبالغ المرتجعة</a><a href="<?php echo url('modules/reports/index.php'); ?>" class="btn btn-outline-primary btn-sm"><i class="fas fa-chart-line me-1"></i>التقارير</a></div></div>
<?php include dirname(__DIR__).'/includes/alerts.php'; ?>
<div class="row g-3 mb-4"><div class="col-md-3"><div class="card fade-in border-primary"><div class="card-body text-center"><i class="fas fa-house-chimney fa-2x text-primary mb-2"></i><h3><?php echo (int)($stats['total_families']??0); ?></h3><p class="text-muted mb-0"><?php echo e(t('dashboard.assigned_families')); ?></p></div></div></div><div class="col-md-3"><div class="card fade-in border-success"><div class="card-body text-center"><i class="fas fa-children fa-2x text-success mb-2"></i><h3><?php echo (int)($stats['total_children']??0); ?></h3><p class="text-muted mb-0"><?php echo e(t('dashboard.sponsored_children')); ?></p></div></div></div><div class="col-md-3"><div class="card fade-in border-warning"><div class="card-body text-center"><i class="fas fa-hand-holding-dollar fa-2x text-warning mb-2"></i><h3><?php echo number_format((float)($stats['total_monthly']??0),0); ?></h3><p class="text-muted mb-0"><?php echo e(t('dashboard.active_monthly_sponsorships')); ?></p></div></div></div><div class="col-md-3"><div class="card fade-in border-info"><div class="card-body text-center"><i class="fas fa-calendar-check fa-2x text-info mb-2"></i><h3><?php echo (int)($ver['fully_verified']??0); ?></h3><p class="text-muted mb-0"><?php echo e(t('dashboard.verified_this_month')); ?></p></div></div></div></div>
<div class="card fade-in border-warning mb-4"><div class="card-header bg-warning bg-opacity-10 d-flex justify-content-between align-items-center"><div><i class="fas fa-clock me-2 text-warning"></i><strong><?php echo e(t('dashboard.pending_receipt_confirmations')); ?></strong><span class="badge bg-warning text-dark ms-2"><?php echo count($pending_batches); ?></span></div><?php if($pending_batches): ?><span class="badge bg-primary"><?php echo e(t('dashboard.progress')); ?>: <?php echo $overall_progress; ?>%</span><?php endif; ?></div><div class="card-body"><?php if(empty($pending_batches)): ?><p class="text-muted text-center py-3 mb-0"><i class="fas fa-check-circle text-success fa-2x d-block mb-2"></i><?php echo e(t('dashboard.no_pending_receipts')); ?></p><?php else: ?><div class="mb-4 p-3 bg-light rounded"><div class="d-flex justify-content-between align-items-center mb-2"><strong><?php echo e(t('dashboard.overall_progress')); ?></strong><span><?php echo (int)$total_confirmed_families; ?>/<?php echo (int)$total_families_transferred; ?> <?php echo e(t('dashboard.families_unit')); ?></span></div><div class="progress" style="height:20px"><div class="progress-bar <?php echo $overall_progress===100?'bg-success':'bg-info'; ?>" style="width:<?php echo $overall_progress; ?>%"> <?php echo $overall_progress; ?>%</div></div></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th><?php echo e(t('common.month')); ?></th><th><?php echo e(t('groups.group')); ?></th><th><?php echo e(t('common.amount')); ?></th><th><?php echo e(t('dashboard.progress')); ?></th><th><?php echo e(t('common.status')); ?></th><th><?php echo e(t('common.actions')); ?></th></tr></thead><tbody><?php foreach($pending_batches as $batch): $progress=$batch['total_families']>0?round(($batch['confirmed_families']/$batch['total_families'])*100):0;$complete=((int)$batch['confirmed_families']===(int)$batch['total_families']&&$batch['total_families']>0); ?><tr class="<?php echo $complete?'table-success':''; ?>"><td><?php echo e($batch['month']); ?></td><td><?php echo e($batch['group_name']??'â€”'); ?></td><td><?php echo number_format((float)$batch['total_amount'],0); ?> <?php echo e(t('hr.currency_sdg')); ?></td><td><div class="d-flex align-items-center gap-2"><div class="progress flex-grow-1" style="height:8px;min-width:80px"><div class="progress-bar <?php echo $complete?'bg-success':($progress?'bg-info':'bg-secondary'); ?>" style="width:<?php echo $progress; ?>%"></div></div><small class="text-muted"><?php echo (int)$batch['confirmed_families']; ?>/<?php echo (int)$batch['total_families']; ?></small></div><?php if((int)$batch['pending_families']>0): ?><small class="text-warning d-block"><?php echo e(t('dashboard.families_awaiting_confirmation',['count'=>(int)$batch['pending_families']])); ?></small><?php endif; ?><?php if($complete): ?><span class="badge bg-success mt-1"><?php echo e(t('dashboard.all_families_confirmed')); ?></span><?php endif; ?></td><td><?php echo $complete?'<span class="badge bg-success">'.e(t('dashboard.ready_to_close')).'</span>':'<span class="badge bg-primary">'.e(t('dashboard.awaiting_confirmation')).'</span>'; ?></td><td><a href="<?php echo APP_URL; ?>modules/accounting/disbursements.php?view=<?php echo (int)$batch['disbursement_id']; ?>" class="btn btn-sm btn-primary"><i class="fas fa-eye"></i> <?php echo e(t('dashboard.view_confirm')); ?></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
<div class="row g-3"><div class="col-lg-5"><div class="card fade-in h-100"><div class="card-header"><i class="fas fa-birthday-cake me-2"></i><?php echo e(t('dashboard.near_legal_age')); ?></div><div class="card-body p-0"><?php if(empty($ageOuts)): ?><p class="text-muted text-center py-4 mb-0"><?php echo e(t('dashboard.no_age_outs')); ?></p><?php else: ?><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead><tr><th><?php echo e(t('common.orphan')); ?></th><th><?php echo e(t('common.family')); ?></th><th><?php echo e(t('dashboard.birth_date')); ?></th></tr></thead><tbody><?php foreach($ageOuts as $a): ?><tr><td><?php echo e($a['child_name']); ?></td><td><a href="<?php echo url('modules/families/view.php?id='.$a['family_id']); ?>"><?php echo e($a['mother_name']); ?></a></td><td><?php echo e($a['birth_date']); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div><div class="col-lg-7"><div class="card fade-in h-100"><div class="card-header"><i class="fas fa-list me-2"></i><?php echo e(t('dashboard.recent_families')); ?></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead><tr><th><?php echo e(t('families.code')); ?></th><th><?php echo e(t('families.mother_name')); ?></th><th><?php echo e(t('common.children')); ?></th><th><?php echo e(t('common.status')); ?></th><th></th></tr></thead><tbody><?php if(empty($families)): ?><tr><td colspan="5" class="text-center text-muted py-4"><?php echo e(t('families.nanny_empty')); ?></td></tr><?php else: foreach($families as $f): ?><tr><td><?php echo e($f['family_code']); ?></td><td><strong><?php echo e($f['mother_name']); ?></strong></td><td><?php echo (int)$f['children_count']; ?></td><td><?php $statusKey=['pending'=>'common.pending','active'=>'common.active','paused'=>'common.paused'][$f['status']]??'common.status'; ?><span class="badge bg-secondary"><?php echo e(t($statusKey)); ?></span></td><td><a href="<?php echo url('modules/families/view.php?id='.$f['id']); ?>" class="btn btn-sm btn-outline-primary" title="<?php echo e(t('common.view')); ?>"><i class="fas fa-eye"></i></a></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></div></div>
